    targets::History {states:Seq::new(run.states.len(),|t:int| Map::new(
        |k:targets::Key| run.states[t].contains_key(k),|k:targets::Key|view(run.states[t][k]))),
        events:Seq::new(run.actions.len(),|t:int| {
